use serde::Serialize;

pub use terrain::Edit;

/// The generator's versions. Add one when a change would alter an existing
/// world, and keep the old behaviour reachable: things are stored against a
/// world id (lots, maps, scores), so `claude-hq@1` must keep generating the
/// same world forever. 1 is the grid city, 2 the organic one, 3 the organic one with
/// its water and lines (HQ 3.15); 4 City Gen v5, the planned city (docs/plans/city-gen-v5.md), built
/// alongside the live @3 until it replaces it.
pub const VERSION: [u32; 4] = [1, 2, 3, 4];

/// The profile a world id's seed and version select: the grid city at @1; at @2
/// a personal island for a `user:` seed, else the Commons; at @3 the same with water.
pub fn profile_for(seed: &str, version: u32) -> profile::Profile {
    let p = match version {
        1 => profile::city(),
        _ if seed.starts_with("user:") => profile::island(),
        _ => profile::commons(),
    };
    let p = if version >= 3 { profile::with_water(p) } else { p };
    // ARENA_WORLDGEN=v5 builds the @3 ids with v5 too: a local Arena, so today's client draws the planned city
    // (never set on the live host)
    let v5 = version >= 4 || (version == 3 && std::env::var("ARENA_WORLDGEN").is_ok_and(|v| v == "v5"));
    // v5: the city fills its island, to V5_SHORE_CM inside the coast (@3's 480 m town left most of the Commons' 1 km
    // island to farmland and wild grass)
    let city_r_cm = match (v5, p.coast_r_cm) { (true, Some(c)) => (c - V5_SHORE_CM).max(p.city_r_cm), _ => p.city_r_cm };
    if !v5 {
        return p;
    }
    // and stands on its plateau (the land fell to the sea's level past @3's 400 m one), the expressway ring a coastal
    // beltway just outside it (inside, every grid street would cross it at grade)
    let ring_r_cm = if p.ring_r_cm > 0 { city_r_cm + V5_BELT_CM } else { 0 };
    profile::Profile { v5, city_r_cm, core_r_cm: city_r_cm, ring_r_cm, ..p }
}

/// City Gen v5: how far inside the coast (cm) the city stops: the shore road, the beach, the piers; and how far past
/// the city's edge (cm) the expressway ring runs.
pub const V5_SHORE_CM: i64 = 15_000;
pub const V5_BELT_CM: i64 = 5_000;

/// Where world `id`'s river meets the sea, in the world's own frame: [x, z] cm of the
/// mouth (the centre line's first point, on the coast) and [dx, dz], the way out to
/// sea there (per mille, a unit vector). None for a world without a river. A pure
/// function of the id (the river ignores edits and tiers), so it is worked out once
/// per process: the archipelago lists it for the big ships' anchorages.
pub fn river_mouth(id: &str) -> Option<[i64; 4]> {
    use std::collections::HashMap;
    use std::sync::{Mutex, OnceLock};
    static MEMO: OnceLock<Mutex<HashMap<String, Option<[i64; 4]>>>> = OnceLock::new();
    let memo = MEMO.get_or_init(Mutex::default);
    if let Some(m) = memo.lock().unwrap().get(id) {
        return *m;
    }
    let mouth = (|| {
        let (seed_str, version) = parse_id(id).ok()?;
        let r = river::River::new(rng::fnv1a64(seed_str.as_bytes()), &profile_for(seed_str, version)).ok()??;
        let (m, up) = (*r.center.first()?, r.center[r.center.len().min(4) - 1]);
        // out of the river's last stretch, else straight out from the island's middle
        let (dx, dz) = if up != m { (m[0] - up[0], m[1] - up[1]) } else { (m[0], m[1]) };
        let l = ((dx * dx + dz * dz) as f64).sqrt().max(1.0);
        Some([m[0], m[1], (dx as f64 * 1000.0 / l).round() as i64, (dz as f64 * 1000.0 / l).round() as i64])
    })();
    memo.lock().unwrap().insert(id.to_string(), mouth);
    mouth
}

#[derive(Serialize)]
pub struct WorldDoc {
    pub id: String,
    pub seed: String,
    pub version: u32,
    pub profile: &'static str,
    pub size_cm: i64,
    pub layers: Layers,
    /// FNV-1a 64 of each layer's JSON, and of the edits applied.
    pub hashes: Hashes,
}

#[derive(Serialize)]
pub struct Layers {
    pub terrain: terrain::Terrain,
    pub districts: districts::Districts,
    pub roads: roads::Roads,
    pub blocks: Vec<city::Block>,
    pub lots: Vec<city::Lot>,
    pub sites: Vec<city::Site>,
    /// Organic worlds (@2): the industry zones and the transit lines.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub zones: Option<Vec<zones::Zone>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub transit: Option<transit::Transit>,
    /// Island worlds (@2): the coast, the sea, the docks and the growth tiers' radii.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub island: Option<island::Island>,
    /// Organic worlds (@2): the river, from the sea to its harbour basin.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub river: Option<river::River>,
    /// @3: the lakes, canals and marina, the piers and the water routes (water.rs); the
    /// metro (metro.rs), the City Line and Island Link (railway.rs), the gondola (gondola.rs).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub water: Option<water::Water>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub metro: Option<metro::Metro>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub rail: Option<railway::Rail>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub gondola: Option<gondola::Gondola>,
}

#[derive(Serialize, Debug, PartialEq)]
pub struct Hashes {
    pub terrain: String,
    pub districts: String,
    pub roads: String,
    pub blocks: String,
    pub lots: String,
    pub sites: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub transit: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub island: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub river: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub water: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub metro: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub rail: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub gondola: Option<String>,
    pub edits: String,
    /// Of all the above: the world's one fingerprint.
    pub world: String,
}

/// Split `seed@version`.
pub fn parse_id(id: &str) -> Result<(&str, u32), String> {
    let (seed, ver) = id.rsplit_once('@').ok_or("a world id is <seed>@<version>")?;
    if seed.is_empty() || seed.len() > 64 || !seed.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_' || b == b':') {
        return Err("a seed is 1-64 letters, digits, '-', '_' or ':'".into());
    }
    let v: u32 = ver.parse().map_err(|_| "the version must be a number")?;
    if !VERSION.contains(&v) {
        return Err(format!("unknown generator version {v} (this server generates {VERSION:?})"));
    }
    Ok((seed, v))
}

fn hash<T: Serialize>(v: &T) -> String {
    format!("{:016x}", rng::fnv1a64(&serde_json::to_vec(v).expect("layers serialise")))
}

/// Generate world `id` (e.g. "claude-hq@1") with `edits` applied to its terrain.
pub fn generate(id: &str, edits: &[Edit]) -> Result<WorldDoc, String> {
    let (seed_str, version) = parse_id(id)?;
    let seed = rng::fnv1a64(seed_str.as_bytes());
    let p = profile_for(seed_str, version);

    let mut river = river::River::new(seed, &p)?;
    // @3: the water, laid with the river before any street grows
    let mut plan = match (&mut river, island::Coast::new(seed, &p)) {
        (Some(r), Some(c)) if p.water => Some(water::lay(seed, &p, r, &c)),
        _ => None,
    };
    let mut base = terrain::generate_with(seed, &p, river.as_ref());
    if let Some(plan) = plan.as_mut() {
        plan.shape(&mut base);
    }
    let (mut city, mut roads, districts, mut tram_routes) = if version == 1 {
        let city = city::generate(seed, &p, &base)?;
        let roads = roads::generate(seed, &p, &base, &city.blocks)?;
        let districts = districts::generate(seed, &p, &base, &city.blocks);
        (city, roads, districts, Vec::new())
    } else {
        let water = plan.as_ref().map_or(Vec::new(), |w| w.outlines());
        organic::generate(seed, &p, &base, river.as_ref(), &water)?
    };
    let mut corridor: Option<corridor::Corridor> = None;
    let (zones, transit, island) = if version == 1 {
        (None, None, None)
    } else {
        let coast = island::Coast::new(seed, &p);
        if coast.is_some() {
            island::trim(&mut roads);
        }
        // City Gen v4 (phase 6): a trumpet where each highway meets the ring, where one fits
        if p.v4 {
            let claim = claims::Airport::of(&city.sites);
            let keep = interchange::Keep { blocks: &city.blocks, claim: claim.as_ref(), river: river.as_ref(), coast: coast.as_ref().map(|c| c.poly.as_slice()) };
            let (made, kept) = interchange::build(&mut roads, &base, &keep);
            // phase 7: the ring under the airport, where it ran behind the terminal
            tunnels::build(&mut roads, claim.as_ref(), &base);
            // phase 8: the City Line's corridor, a boulevard cut under its alignment
            if version >= 3 {
                let mut polys: Vec<Vec<[i64; 2]>> = plan.as_ref().map_or(Vec::new(), |w| w.outlines().iter().map(|b| b.iter().map(|q| [q.0, q.1]).collect()).collect());
                if let Some(r) = river.as_ref() {
                    polys.push(r.poly.clone());
                }
                let shore: Option<Vec<[i64; 2]>> = coast.as_ref().map(|c| c.poly.iter().map(|q| [q.0, q.1]).collect());
                let (lots, sites) = (city.lots.clone(), city.sites.clone());
                let c = lines::Ctx { seed, profile: &p, terrain: &base, roads: &roads, lots: &lots, sites: &sites, river: river.as_ref(), water: &polys, coast: shore.as_deref() };
                // (the alignment, and whether it crosses water, on the streets as they are)
                let found = railway::alignment(&c).map(|cl| {
                    let land = lines::Land::new(&c);
                    let wet: Vec<bool> = corridor::samples(&cl.path).into_iter().map(|q| land.wet(q)).collect();
                    (cl, wet)
                });
                if let Some((cl, wet)) = found {
                    let mut r2 = roads.clone();
                    match corridor::cut(&mut r2, &mut city, &base, &cl, &wet, claim.as_ref()) {
                        Ok(k) => {
                            roads = r2;
                            corridor = Some(k);
                        }
                        Err(why) => {
                            if std::env::var("HQ_IX").is_ok() {
                                eprintln!("corridor: none ({why})");
                            }
                        }
                    }
                }
            }
            // (HQ_IX=1 worldgen <id>: what each junction became, for tuning)
            if std::env::var("HQ_IX").is_ok() {
                eprintln!("interchanges: {made} made, kept at grade: {kept:?}");
            }
            // HQ spacing: the HQ pool, drawn by spacing on the lots and roads as they now are,
            // the City Line's boulevard cut (organic/hq.rs)
            organic::hq::draw(&p, &base, &roads, &mut city)?;
        }
        civic::outside(&p, &base, &roads, &mut city, river.as_ref());
        // a personal island's first bus loop keeps to its tier-2 town (20 m in from the ring)
        let inner = (p.name == "island").then(|| island::RADII_CM[1] - 2_000);
        // City Gen v4: a side of a route the City Line's boulevard cut with too few stations gets the
        // rest on platforms
        if p.v4 {
            transit::route_stations(&roads, &mut city.sites, &city.lots, &mut tram_routes);
        }
        let mut transit = transit::generate(&roads, &city.sites, &city.lots, inner, &tram_routes);
        // City Gen v4: where a station's best stretch is cut by a side street meeting its tram road at a
        // T, that side street ends short of it (a cul-de-sac), and the lines are drawn again
        if p.v4 && transit::close_mouths(&mut roads, &transit, &city.sites, &city.lots) > 0 {
            transit::route_stations(&roads, &mut city.sites, &city.lots, &mut tram_routes);
            transit = transit::generate(&roads, &city.sites, &city.lots, inner, &tram_routes);
        }
        let island = coast.map(|c| island::grow(&p, &c, &mut roads, &mut city, &mut transit));
        // City Gen v4 (phase 2): a tram runs down the middle of its street until phase 8
        // gives it its own bed, so a street a tram line runs on has no median yet
        roads.untram_unused(&transit);
        roads.tram_on(&transit);
        // phase 9: the tram stations on their tracks
        if p.v4 {
            transit::stations(&roads, &mut transit, &mut city.sites, &city.lots, &base);
        }
        roads.trams_in_the_middle(&transit);
        // phase 3: each junction's control, by the roads that meet there
        if p.v4 {
            let clear: Vec<Vec<(i64, i64)>> = city.lots.iter().filter_map(|l| l.poly.as_ref()).chain(city.sites.iter().filter_map(|s| s.poly.as_ref())).map(|p| p.iter().map(|q| (q[0], q[1])).collect()).collect();
            roads.junctions(&transit, &clear);
        }
        (Some(zones::layer(seed, &city.blocks)), Some(transit), island)
    };

    let mut terrain = base;
    terrain.apply(edits)?;
    roads.seat(&terrain, &p)?;
    roads.carve(&mut terrain, |q| river.as_ref().is_some_and(|r| r.wet(q)));
    // @3: the rest of the water, then the lines, their claims made sites before every
    // lot and site is seated on the final ground
    let water = match (plan, river.as_ref(), island::Coast::new(seed, &p)) {
        (Some(plan), Some(r), Some(c)) => Some(plan.finish(&p, &roads, &mut city, r, &c)),
        _ => None,
    };
    let (metro, rail, gondola) = if version >= 3 {
        let (m, r, g) = lines(seed, &p, &terrain, &roads, &mut city, river.as_ref(), water.as_ref(), island.as_ref(), corridor.as_ref().map(|k| &k.cl))?;
        (Some(m), Some(r), Some(g))
    } else {
        (None, None, None)
    };
    city.seat(&terrain);

    let layers = Layers {
        terrain, districts, roads, blocks: city.blocks, lots: city.lots, sites: city.sites, zones, transit, island, river, water, metro, rail, gondola,
    };
    let mut hashes = Hashes {
        terrain: hash(&layers.terrain),
        districts: hash(&layers.districts),
        roads: hash(&layers.roads),
        blocks: hash(&layers.blocks),
        lots: hash(&layers.lots),
        sites: hash(&layers.sites),
        transit: layers.transit.as_ref().map(hash),
        island: layers.island.as_ref().map(hash),
        river: layers.river.as_ref().map(hash),
        water: layers.water.as_ref().map(hash),
        metro: layers.metro.as_ref().map(hash),
        rail: layers.rail.as_ref().map(hash),
        gondola: layers.gondola.as_ref().map(hash),
        edits: hash(&edits),
        world: String::new(),
    };
    hashes.world = hash(&hashes);
    Ok(WorldDoc { id: format!("{seed_str}@{version}"), seed: seed_str.to_string(), version, profile: p.name, size_cm: p.size_cm, layers, hashes })
}

/// @3: the metro, the railway and the gondola, planned in that order on the finished
/// world (each planner sees the claims of those before it applied), their claims made
/// sites.
#[allow(clippy::too_many_arguments)] // the world the lines are planned on
fn lines(
    seed: u64,
    p: &profile::Profile,
    terrain: &terrain::Terrain,
    roads: &roads::Roads,
    city: &mut city::City,
    river: Option<&river::River>,
    water: Option<&water::Water>,
    island: Option<&island::Island>,
    cl: Option<&railway::Cl>,
) -> Result<(metro::Metro, railway::Rail, gondola::Gondola), String> {
    let mut polys: Vec<Vec<[i64; 2]>> = water.map_or(Vec::new(), |w| w.bodies.iter().map(|b| b.poly.clone()).collect());
    if let Some(r) = river {
        polys.push(r.poly.clone());
    }
    let coast = island.map(|i| i.coast.as_slice());
    let ctx = |city: &city::City| -> (Vec<city::Lot>, Vec<city::Site>) { (city.lots.clone(), city.sites.clone()) };
    let (lots, sites) = ctx(city);
    let c = lines::Ctx { seed, profile: p, terrain, roads, lots: &lots, sites: &sites, river, water: &polys, coast };
    let (metro, mut taken) = metro::plan(&c)?;
    claim(city, &taken)?;
    let (lots, sites) = ctx(city);
    let c = lines::Ctx { lots: &lots, sites: &sites, ..c };
    let (rail, rc) = railway::plan(&c, &metro, cl)?;
    claim(city, &rc)?;
    taken.extend(rc);
    let (lots, sites) = ctx(city);
    let c = lines::Ctx { lots: &lots, sites: &sites, ..c };
    let (gondola, gc) = gondola::plan(&c, &taken)?;
    claim(city, &gc)?;
    Ok((metro, rail, gondola))
}

/// Apply a planner's claims: each a site of the claim's kind, id, tier, footprint and
/// front; a claimed lot is no longer a lot (never an HQ's: that is an error). The lots
/// are numbered again (ids and growth ranks in order), as the organic generator leaves them.
fn claim(city: &mut city::City, claims: &[lines::Claim]) -> Result<(), String> {
    use organic::geom::{extent, left, P};
    let mut gone = std::collections::BTreeSet::new();
    for c in claims {
        if let Some(id) = c.lot {
            let l = city.lots.iter().find(|l| l.id == id).ok_or_else(|| format!("claim {}: no lot {id}", c.id))?;
            if l.kind == "hq" {
                return Err(format!("claim {}: lot {id} is an HQ's", c.id));
            }
            gone.insert(id);
        }
        if city.sites.iter().any(|s| s.id == c.id) {
            return Err(format!("claim {}: the site id is taken", c.id));
        }
    }
    for c in claims {
        let poly: Vec<P> = c.poly.iter().map(|q| (q[0], q[1])).collect();
        let f: P = (c.front[0], c.front[1]);
        let (w, d) = if poly.is_empty() {
            (0, 0)
        } else {
            let ((a0, a1), (b0, b1)) = (extent(&poly, left(f)), extent(&poly, f));
            (a1 - a0, b1 - b0)
        };
        let block = c
            .lot
            .and_then(|id| city.lots.iter().find(|l| l.id == id).map(|l| l.block))
            .or_else(|| city.blocks.iter().min_by_key(|b| ((b.x - c.x).pow(2) + (b.z - c.z).pow(2), b.id)).map(|b| b.id))
            .unwrap_or(0);
        city.sites.push(city::Site {
            id: c.id.clone(), kind: c.kind, block, x: c.x, y: 0, z: c.z, w, d,
            facing: if c.front[1] >= 0 { city::Facing::North } else { city::Facing::South },
            tier: Some(c.tier), poly: (!c.poly.is_empty()).then(|| c.poly.clone()), front: Some(c.front), view: None,
        });
    }
    retire_lots(city, &gone);
    Ok(())
}

/// Take lots `gone` out of the city, the rest numbered again (ids and growth ranks in order).
fn retire_lots(city: &mut city::City, gone: &std::collections::BTreeSet<u32>) {
    if !gone.is_empty() {
        city.lots.retain(|l| !gone.contains(&l.id));
        let mut by_grow: Vec<(u32, usize)> = city.lots.iter().enumerate().map(|(k, l)| (l.grow.unwrap_or(u32::MAX), k)).collect();
        by_grow.sort();
        for (rank, &(g, k)) in by_grow.iter().enumerate() {
            if g != u32::MAX {
                city.lots[k].grow = Some(rank as u32);
            }
        }
        for (k, l) in city.lots.iter_mut().enumerate() {
            l.id = k as u32;
        }
    }
}
